import base64,json
from pathlib import Path
P=Path(__file__).resolve().parent;ROOT=P.parents[2];data=json.loads((P/'motion-contract.json').read_text());paths={r['body']['path'] for rows in data['variants'].values() for r in rows}|{data['head']['path']}
images={p:'data:image/png;base64,'+base64.b64encode((ROOT/p).read_bytes()).decode() for p in paths}
html='''<!doctype html><meta charset="utf-8"><title>Coherent outfit / neck motion validation</title><style>body{background:#1d2935;color:#edf1fa;font:16px system-ui;margin:24px}canvas{background:#344351;width:384px;height:512px}select,button,input{font:inherit}p{max-width:900px}.status{color:#ffc17c}</style><h1>Coherent body + outfit / motion validation</h1><canvas id="view" width="384" height="512"></canvas><p><select id="variant"><option value="review">Isolated recovery-key repair</option><option value="raw8">Before / v38 lateral hitch</option></select><select id="clock"><option value="source">Source / 1300ms</option><option value="game">Game / 700ms</option></select><input id="frame" type="range" min="0" max="7" value="0"><button id="play">Play once</button><label><input id="guides" type="checkbox">Observed collar edges</label><select id="background"><option value="#344351">Slate</option><option value="#ffffff">White</option><option value="#101722">Dark</option></select></p><p id="status"></p><p class="status">One-key repair candidate: same seven other poses, head scale and clocks. Read the combined contact/trajectory and visual review before acceptance.</p><script>
const DATA=__DATA__,SRC=__IMAGES__,images={},ctx=document.getElementById('view').getContext('2d');let ready=false,index=0,variant='review',running=false,start=0;const material=[];
function opaque(im,name){const c=document.createElement('canvas');c.width=im.width;c.height=im.height;const x=c.getContext('2d');x.drawImage(im,0,0);const d=x.getImageData(0,0,c.width,c.height);let changed=0;for(let k=3;k<d.data.length;k+=4)if(d.data[k]>=240&&d.data[k]<255){d.data[k]=255;changed++}x.putImageData(d,0,0);material.push({name,alpha_pixels_changed:changed});return c}
Promise.all(Object.entries(SRC).map(([n,src])=>new Promise(resolve=>{const im=new Image;im.onload=()=>{images[n]=opaque(im,n);resolve()};im.src=src}))).then(()=>{ready=true;draw()});
function render(i,v='review',mode='full',guides=false){const q=DATA.variants[v][i],body=images[q.body.path],head=images[DATA.head.path];ctx.setTransform(1,0,0,1,0,0);ctx.clearRect(0,0,384,512);if(mode==='full'||mode==='body'){ctx.setTransform(...q.body_matrix);ctx.drawImage(body,0,0)}if(mode==='full'||mode==='head'){ctx.setTransform(...q.head_matrix);ctx.drawImage(head,0,0)}if(mode==='full'||mode==='collar'){ctx.save();ctx.setTransform(...q.body_matrix);ctx.beginPath();q.collar_foreground_polygon_native.forEach((p,k)=>k?ctx.lineTo(...p):ctx.moveTo(...p));ctx.closePath();ctx.clip();ctx.drawImage(body,0,0);ctx.restore()}ctx.setTransform(1,0,0,1,0,0);if(guides){ctx.strokeStyle='#61ffbb';ctx.lineWidth=2;ctx.beginPath();for(let k=0;k<2;k++){const p=q.body_collar_lip_points_native[k],m=q.body_matrix,x=m[0]*p[0]+m[2]*p[1]+m[4],y=m[1]*p[0]+m[3]*p[1]+m[5];k?ctx.lineTo(x,y):ctx.moveTo(x,y)}ctx.stroke()}}
function draw(){if(!ready)return;render(index,variant,'full',document.getElementById('guides').checked);document.getElementById('frame').value=index;document.getElementById('variant').value=variant;document.getElementById('status').textContent=variant+' / frame '+(index+1)+' / source '+DATA.variants[variant][index].source_time_seconds.toFixed(3)+'s'}
document.getElementById('frame').oninput=e=>{running=false;index=+e.target.value;draw()};document.getElementById('variant').onchange=e=>{variant=e.target.value;draw()};document.getElementById('clock').onchange=()=>{running=false;index=0;draw()};document.getElementById('guides').onchange=draw;document.getElementById('background').onchange=e=>ctx.canvas.style.background=e.target.value;
function tick(t){if(!running)return;const elapsed=t-start,game=document.getElementById('clock').value==='game',active=game?700:1300;while(index<7&&(game?(index+1)*100:DATA.variants[variant][index+1].source_time_seconds*1000)<=elapsed)index++;draw();if(elapsed>=active+600){running=false;return}requestAnimationFrame(tick)}document.getElementById('play').onclick=()=>{index=0;running=true;start=performance.now();requestAnimationFrame(tick)};
window.motion={get ready(){return ready},get index(){return index},get running(){return running},data:DATA,material,frame(i,v='review',mode='full'){render(i,v,mode);return ctx.canvas.toDataURL('image/png')},select(v,i=index){variant=v;index=i;draw()}};
</script>'''
(P/'motion-preview.html').write_text(html.replace('__DATA__',json.dumps(data,separators=(',',':'))).replace('__IMAGES__',json.dumps(images,separators=(',',':'))))
